    @Test
    /**
     * Full Create-Read-Update-Delete of a ModelPortfolio, through a ModelPortfolioTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on ModelPortfolioTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on ModelPortfolioTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new ModelPortfolio.
     *
     * @return    ModelPortfolio
     */
    public ModelPortfolio testCreate() throws Throwable {
    ModelPortfolio entity = null;

    LOGGER.info( "ModelPortfolioTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a ModelPortfolio");

    StringBuilder msg = new StringBuilder( "-- Failed to create a ModelPortfolio" );

    try {
        entity = service.createModelPortfolio( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getModelPortfolioId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a ModelPortfolio with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a ModelPortfolio.
     *
     * @return    ModelPortfolio
     */
    public ModelPortfolio testRead() throws Throwable {
    LOGGER.info( "ModelPortfolioTest:testRead()" );
    LOGGER.info( "-- Reading a previously created ModelPortfolio" );

    ModelPortfolio entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read ModelPortfolio with primary key" );
    msg.append( theId );

    try {
        entity = service.getModelPortfolio( new ModelPortfolioFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getModelPortfolioId();

        LOGGER.info( "-- Successfully found ModelPortfolio " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a ModelPortfolio.
     *
     * @return    ModelPortfolio
     */
    public ModelPortfolio testUpdate() throws Throwable {
    LOGGER.info( "ModelPortfolioTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a ModelPortfolio." );

    StringBuilder msg = new StringBuilder( "Failed to update a ModelPortfolio : " );
    ModelPortfolio entity = null;

    try {
        UpdateModelPortfolioCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setModelPortfolioId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created ModelPortfolio." );

        entity = service.updateModelPortfolio( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved ModelPortfolio - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a ModelPortfolio.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "ModelPortfolioTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created ModelPortfolio." );

    try {
        DeleteModelPortfolioCommand deleteCommand = new DeleteModelPortfolioCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted ModelPortfolio with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete ModelPortfolio with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all ModelPortfolios.
     *
     * @return    Collection
     */
    public List<ModelPortfolio> testGetAll() throws Throwable {
    LOGGER.info( "ModelPortfolioTest:testGetAll() - Retrieving Collection of ModelPortfolios:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ModelPortfolio : " );
    List<ModelPortfolio> collection  = null;

    try {
        // call the static get method on the ModelPortfolioService
        collection = service.getAllModelPortfolio();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ModelPortfolio currEntity  = null;
            Iterator<ModelPortfolio> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getModelPortfolioId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

